import { useState, useEffect } from 'react'

// ── initial display values (same as original HTML)
const INIT_BASE = { LENGTH: 1, AREA: 1, FORCE: 100, STRESSES: 100, MOMENTS: 100,
  'UNIFORM LOADING (Linear)': 100, 'UNIFORM LOADING (Area)': 100 }

export default function UnitConversion() {
  const [groups, setGroups] = useState([])
  // values: { 'FORCE.KN': '100', ... }
  const [values, setValues] = useState({})
  const dataBase = window.location.pathname.replace(/\/$/, '') + '/'

  useEffect(() => {
    fetch(`${dataBase}data/unitGroups.json`)
      .then(r => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json() })
      .then(data => {
        setGroups(data)
        const init = {}
        data.forEach(g => {
          const base = INIT_BASE[g.category] ?? 1
          Object.entries(g.units).forEach(([u, meta]) => {
            if (!meta.virtual) {
              const v = base * meta.factor
              init[`${g.category}.${u}`] = fmtNum(v, meta.precision)
            }
          })
          // ft-in special
          if (g.units['ft-in']) {
            const { feet, inches } = toFtIn(base)
            init[`${g.category}.ft-in-ft`] = String(feet)
            init[`${g.category}.ft-in-in`] = fmtNum(inches, 3)
          }
        })
        setValues(init)
      })
      .catch(e => console.error('unitGroups.json load error:', e))
  }, [])

  function handleChange(g, changedUnit, rawVal) {
    const num = parseFloat(rawVal)
    const key = `${g.category}.${changedUnit}`
    if (isNaN(num) || !isFinite(num)) { setValues(v => ({ ...v, [key]: rawVal })); return }

    // convert changedUnit → base
    const toBase = num / g.units[changedUnit].factor
    const next = { ...values }
    // update all non-virtual units
    Object.entries(g.units).forEach(([u, meta]) => {
      if (meta.virtual) return
      next[`${g.category}.${u}`] = fmtNum(toBase * meta.factor, meta.precision)
    })
    // ft-in special
    if (g.units['ft-in']) {
      const { feet, inches } = toFtIn(toBase)
      next[`${g.category}.ft-in-ft`] = String(feet)
      next[`${g.category}.ft-in-in`] = fmtNum(inches, 3)
    }
    next[key] = rawVal
    setValues(next)
  }

  function handleFtIn(g, part, rawVal) {
    const ftVal  = part === 'ft' ? parseFloat(rawVal) || 0 : parseFloat(values[`${g.category}.ft-in-ft`]) || 0
    const inVal  = part === 'in' ? parseFloat(rawVal) || 0 : parseFloat(values[`${g.category}.ft-in-in`]) || 0
    const base_m = (ftVal * 12 + inVal) / 39.3701   // ft+in → m
    const next   = { ...values }
    Object.entries(g.units).forEach(([u, meta]) => {
      if (meta.virtual) return
      next[`${g.category}.${u}`] = fmtNum(base_m * meta.factor, meta.precision)
    })
    next[`${g.category}.ft-in-ft`] = part === 'ft' ? rawVal : String(ftVal)
    next[`${g.category}.ft-in-in`] = part === 'in' ? rawVal : fmtNum(inVal, 3)
    setValues(next)
  }

  if (!groups.length) return <div style={{ color: 'var(--tx-muted)' }}>Loading...</div>

  return (
    <div>
      <h3 style={titleStyle}>UNIT CONVERSION</h3>

      {/* 7-column grid — one column per category */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(7, minmax(0, 1fr))',
        gap: 10,
      }}>
        {groups.map(g => (
          <div key={g.category} style={colCard}>
            <div style={catTitle}>{g.category}</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              {Object.entries(g.units).map(([unit, meta]) => {
                if (meta.virtual && unit === 'ft-in') {
                  return (
                    <div key={unit} className="uc-cell">
                      <label style={cellLabel}>{meta.label}</label>
                      <div style={{ display: 'flex', gap: 4 }}>
                        <div style={{ flex: 1 }}>
                          <input
                            type="text" inputMode="numeric"
                            value={values[`${g.category}.ft-in-ft`] ?? ''}
                            onChange={e => handleFtIn(g, 'ft', e.target.value)}
                            style={{ ...cellInput, textAlign: 'center', background: 'var(--bg-input)', color: 'var(--tx-primary)' }}
                            placeholder="ft"
                          />
                          <div style={subUnit}>ft</div>
                        </div>
                        <div style={{ flex: 1 }}>
                          <input
                            type="text" inputMode="numeric"
                            value={values[`${g.category}.ft-in-in`] ?? ''}
                            onChange={e => handleFtIn(g, 'in', e.target.value)}
                            style={{ ...cellInput, textAlign: 'center', background: 'var(--bg-input)', color: 'var(--tx-primary)' }}
                            placeholder="in"
                          />
                          <div style={subUnit}>in</div>
                        </div>
                      </div>
                    </div>
                  )
                }
                if (meta.virtual) return null
                const v = values[`${g.category}.${unit}`] ?? ''
                return (
                  <div key={unit} className="uc-cell">
                    <label style={cellLabel}>{meta.label}</label>
                    <input
                      type="text" inputMode="numeric"
                      value={v}
                      onChange={e => handleChange(g, unit, e.target.value)}
                      readOnly={meta.inputable === false}
                      style={{
                        ...cellInput,
                        background: meta.inputable === false ? 'var(--bg-inset)' : 'var(--bg-input)',
                        fontWeight: meta.inputable === false ? 700 : 400,
                        color: meta.inputable === false ? 'var(--ac-main)' : 'var(--tx-primary)',
                        cursor: meta.inputable === false ? 'default' : 'text',
                      }}
                    />
                  </div>
                )
              })}
            </div>
          </div>
        ))}
      </div>

      {/* Reference table — identical to original HTML */}
      <div style={{ marginTop: 32 }}>
        <h4 style={{ fontSize: '1.1rem', fontWeight: 700, marginBottom: 16, color: 'var(--tx-primary)', paddingBottom: 8, borderBottom: '1px solid var(--bd-subtle)' }}>
          Reference: Structural Unit Conversion Factors
        </h4>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
          <thead>
            <tr>
              {['Category', 'From', 'To', 'Multiply by'].map(h => (
                <th key={h} style={refTh}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {REF_TABLE.map((row, i) => (
              <tr key={i} style={{ background: row.category ? 'var(--bg-inset)' : 'transparent' }}>
                <td style={{ ...refTd, fontWeight: row.category ? 700 : 400, color: row.category ? 'var(--ac-main)' : 'var(--tx-muted)' }}>
                  {row.category ?? ''}
                </td>
                <td style={refTd}>{row.from}</td>
                <td style={refTd}>{row.to}</td>
                <td style={{ ...refTd, fontWeight: 700, color: 'var(--val-pos)', fontFamily: 'monospace' }}>{row.factor}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

// ── helpers ──────────────────────────────────────────────────
function fmtNum(v, precision = 4) {
  if (!isFinite(v)) return ''
  return +v.toFixed(precision) + ''
}

function toFtIn(meters) {
  const totalIn = meters * 39.3701
  const feet    = Math.floor(totalIn / 12)
  const inches  = totalIn - feet * 12
  return { feet, inches }
}

const REF_TABLE = [
  { category: 'Forces',          from: 'kip',       to: 'kN',     factor: 4.448 },
  { category: null,              from: 'lb',        to: 'N',      factor: 4.448 },
  { category: null,              from: 'kN',        to: 'kip',    factor: 0.2248 },
  { category: 'Stresses',        from: 'ksi',       to: 'MPa',    factor: 6.895 },
  { category: null,              from: 'psi',       to: 'MPa',    factor: '0.006895' },
  { category: null,              from: 'MPa',       to: 'ksi',    factor: 0.1450 },
  { category: null,              from: 'MPa',       to: 'psi',    factor: 145.0 },
  { category: 'Moments',         from: 'ft-kip',    to: 'kN-m',   factor: 1.356 },
  { category: null,              from: 'kN-m',      to: 'ft-kip', factor: 0.7376 },
  { category: 'Uniform Loading', from: 'kip/ft',    to: 'kN/m',   factor: 14.59 },
  { category: null,              from: 'kN/m',      to: 'kip/ft', factor: 0.06852 },
  { category: null,              from: 'kip/ft²',   to: 'kN/m²',  factor: 47.88 },
  { category: null,              from: 'psf',       to: 'N/m²',   factor: 47.88 },
  { category: null,              from: 'kN/m²',     to: 'kip/ft²',factor: 0.02089 },
]

// ── styles ────────────────────────────────────────────────────
const titleStyle = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 20, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const colCard    = { background: 'var(--bg-card)', border: '1px solid var(--bd-subtle)', borderRadius: 8, padding: 8, overflow: 'hidden' }
const catTitle   = { fontSize: 10, fontWeight: 700, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--ac-main)', marginBottom: 8, paddingBottom: 5, borderBottom: '1px solid var(--bd-subtle)' }
const cellLabel  = { display: 'block', fontSize: 10, color: 'var(--tx-secondary)', marginBottom: 2, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }
const cellInput  = { width: '100%', borderRadius: 4, border: '1px solid var(--bd-subtle)', padding: '4px 5px', fontSize: 12, textAlign: 'center', outline: 'none' }
const subUnit    = { fontSize: 9, color: 'var(--tx-muted)', textAlign: 'center', marginTop: 1 }
const refTh      = { background: 'var(--bg-inset)', color: 'var(--ac-main)', fontWeight: 600, padding: '7px 10px', textAlign: 'left', borderBottom: '2px solid var(--bd-accent)', fontSize: 12 }
const refTd      = { padding: '5px 10px', borderBottom: '1px solid var(--bd-subtle)', color: 'var(--tx-primary)', fontSize: 12 }
